def _collapse_groups(sizes_strides):
    """Collapse dims into maximal contiguous groups (innermost first)."""
    groups = []
    for size, stride in reversed(sizes_strides):
        if size == 1:
            continue
        if groups:
            psize, pstride = groups[-1]
            if pstride * psize == stride:
                groups[-1] = (psize * size, pstride)
                continue
        groups.append((size, stride))
    return groups


def _strided_args(shape, strides, dim):
    pairs = [(shape[k], strides[k]) for k in range(len(shape)) if k != dim]
    groups = _collapse_groups(pairs)
    args = []
    div = 1
    for size, stride in groups:
        args.extend((div, size, stride))
        div *= size
    if len(args) > 12:
        return None
    while len(args) < 12:
        args.extend((1, 1, 0))
    return args


def _num_warps(bn):
    if bn <= 128:
        return 1
    if bn <= 512:
        return 2
    if bn <= 1024:
        return 4
    return 8


def median_dim_values(inp, dim=0, keepdim=False, *out_args, values=None, indices=None):
    logger.debug("GEMS_KUNLUNXIN MEDIAN_DIM_VALUES")
    if inp.dtype == torch.float64:
        raise NotImplementedError(
            "median_dim_values: float64 is not supported on Kunlunxin"
        )
    with torch_device_fn.device(inp.device):
        return _median_dim_values(
            inp, dim, keepdim, *out_args, values=values, indices=indices
        )


def _median_dim_values(inp, dim=0, keepdim=False, *out_args, values=None, indices=None):
    if out_args:
        if len(out_args) == 1 and isinstance(out_args[0], (tuple, list)):
            values, indices = out_args[0]
        elif len(out_args) >= 2:
            values, indices = out_args[0], out_args[1]
    shape = inp.shape
    nd = len(shape)
    if isinstance(dim, str):
        names = getattr(inp, "names", (None,) * nd)
        if dim not in names:
            raise RuntimeError(f"Name '{dim}' not found in Tensor{names}.")
        dim = names.index(dim)
    limit = max(nd, 1)
    if dim < -limit or dim >= limit:
        raise IndexError(
            f"Dimension out of range (expected [{-limit}, {limit - 1}], got {dim})"
        )
    dim %= limit
    dt = inp.dtype

    kind_bits = KIND_AND_BITS.get(dt)
    if kind_bits is None and dt != torch.int64:
        raise NotImplementedError(f"median_dim_values: unsupported dtype {dt}")
    kind, keybits = kind_bits if kind_bits is not None else (K_I64, None)

    if nd == 0:
        N = 1
        M = 1
        inner = 1
        contig = True
    else:
        N = shape[dim]
        if N == 0:
            raise IndexError(
                "median(): Expected reduction dim %d to have non-zero size." % dim
            )
        inner = 1
        for s in shape[dim + 1 :]:
            inner *= s
        M = inp.numel() // N
        contig = inp.is_contiguous()

    oshape = list(shape)
    if nd:
        if keepdim:
            oshape[dim] = 1
        else:
            del oshape[dim]
    if values is None or indices is None:
        values = torch.empty(oshape, dtype=dt, device=inp.device)
        indices = torch.empty(oshape, dtype=torch.int64, device=inp.device)
    else:
        if values.device != inp.device or indices.device != inp.device:
            raise RuntimeError(
                "median_dim_values: values/indices must be on the input device"
            )
        if indices.dtype != torch.int64:
            raise RuntimeError("median_dim_values: indices must be int64")
        if values.dtype != dt:
            raise RuntimeError("median_dim_values: values dtype must match input")
        if tuple(values.shape) != tuple(oshape):
            values.resize_(oshape)
        if tuple(indices.shape) != tuple(oshape):
            indices.resize_(oshape)

    if M == 0:
        return MedianResult(values, indices)

    # This backend uses one tile per reduction; larger tiles have not been
    # validated and must not fail later in the device compiler.
    if N > 4096:
        raise NotImplementedError(
            "median_dim_values: reduction size exceeds supported limit 4096"
        )

    result_values, result_indices = values, indices
    if not values.is_contiguous():
        values = torch.empty(values.shape, dtype=values.dtype, device=values.device)
    if not indices.is_contiguous():
        indices = torch.empty(indices.shape, dtype=indices.dtype, device=indices.device)

    def finish():
        if values is not result_values:
            copy_(result_values, values)
        if indices is not result_indices:
            copy_(result_indices, indices)
        return MedianResult(result_values, result_indices)

    bn = _next_pow2(N)
    if bn < 64:
        bn = 64
    warps = _num_warps(bn)
    zero = 0.0 if dt.is_floating_point else 0
    nzero = _NEG_ZERO if dt.is_floating_point else 0
    fill = _LOWEST.get(dt, 0)
    nopad = bn == N

    if kind == K_I64:
        _median_i64_kernel[(M,)](
            inp,
            values,
            indices,
            N,
            tuple(shape),
            tuple(inp.stride()),
            dim,
            BLOCK_N=bn,
            num_warps=warps,
        )
        return finish()

    if contig:
        _median_contig_kernel[(M,)](
            inp,
            values,
            indices,
            N,
            inner,
            BLOCK_N=bn,
            KIND=kind,
            KEYBITS=keybits,
            ZERO=zero,
            NZERO=nzero,
            FILL=fill,
            NOPAD=nopad,
            num_warps=warps,
        )
    else:
        sargs = _strided_args(shape, inp.stride(), dim)
        if sargs is None:
            raise NotImplementedError(
                "median_dim_values: input layout needs too many stride groups"
            )
